export class ApplicationManifestClient {
    baseUrl;
    token;
    constructor(baseUrl = '', token = '') {
        this.baseUrl = baseUrl;
        this.token = token;
    }
    async request(path, options) { const response = await fetch(`${this.baseUrl}${path}`, { ...options, headers: { ...(options?.body ? { 'Content-Type': 'application/json' } : {}), ...(this.token ? { Authorization: `Bearer ${this.token}` } : {}), ...options?.headers } }); const text = await response.text(); let result = {}; try {
        result = text ? JSON.parse(text) : {};
    }
    catch {
        result = { error: text };
    } if (!response.ok)
        throw Object.assign(new Error(response.status === 401 || response.status === 403 ? 'Authentication failed. Check the configured managed credentials.' : result.message || result.error || 'Manifest request failed'), { status: response.status, result }); return result; }
    createDraft(applicationId, baseRevisionId) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/drafts`, { method: 'POST', body: JSON.stringify({ base_revision_id: baseRevisionId }) }); }
    getDraft(applicationId, draftId) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/drafts/${encodeURIComponent(draftId)}`); }
    updateDraft(applicationId, draft, manifest) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/drafts/${encodeURIComponent(draft.draft_id)}`, { method: 'PUT', headers: { 'If-Version': String(draft.version) }, body: JSON.stringify({ manifest }) }); }
    validateDraft(applicationId, draftId) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/drafts/${encodeURIComponent(draftId)}/validate`, { method: 'POST' }); }
    commitDraft(applicationId, draftId) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/drafts/${encodeURIComponent(draftId)}/commit`, { method: 'POST' }); }
    revisions(applicationId) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions`); }
    diff(applicationId, revision, from) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/diff${from === undefined ? '' : `?from=${encodeURIComponent(from)}`}`); }
    preview(applicationId, revision, policy) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/preview`, { method: 'POST', body: JSON.stringify({ policy }) }); }
    environments(applicationId) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/environments`); }
    readiness(applicationId, environment, revision) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/environments/${encodeURIComponent(environment)}/readiness${revision === undefined ? '' : `?revision=${encodeURIComponent(revision)}`}`); }
    promoteEnvironment(applicationId, environment, revision, expectedCurrentRevision, reason = '', approveDestructiveChanges = false) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/environments/${encodeURIComponent(environment)}/promote`, { method: 'POST', body: JSON.stringify({ revision, expected_current_revision: expectedCurrentRevision, reason, approve_destructive_changes: approveDestructiveChanges }) }); }
    rollback(applicationId, environment, targetRevision, expectedCurrentRevision, reason = '') { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/environments/${encodeURIComponent(environment)}/rollback`, { method: 'POST', body: JSON.stringify({ target_revision: targetRevision, expected_current_revision: expectedCurrentRevision, reason }) }); }
    history(applicationId, environment) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/environments/${encodeURIComponent(environment)}/history`); }
    promote(applicationId, revision, environment, reason = '', expectedCurrentRevision, approveDestructiveChanges = false) { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/promote`, { method: 'POST', body: JSON.stringify({ environment, reason, expected_current_revision: expectedCurrentRevision, approve_destructive_changes: approveDestructiveChanges }) }); }
    runtime(applicationId, revision, environment = 'production') { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/runtime?environment=${encodeURIComponent(environment)}`); }
    run(applicationId, revision, environment = 'preview') { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/run`, { method: 'POST', body: JSON.stringify({ environment }) }); }
    stop(applicationId, revision, environment = 'preview') { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/stop`, { method: 'POST', body: JSON.stringify({ environment }) }); }
    executeAction(applicationId, revision, action, input, environment = 'preview') { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/actions/${encodeURIComponent(action)}?environment=${encodeURIComponent(environment)}`, { method: 'POST', body: JSON.stringify(input) }); }
    executeQuery(applicationId, revision, query, environment = 'preview') { return this.request(`/api/applications/${encodeURIComponent(applicationId)}/revisions/${encodeURIComponent(revision)}/queries/${encodeURIComponent(query)}?environment=${encodeURIComponent(environment)}`, { method: 'POST' }); }
}
